extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # Watchman Monitoring Computer URL Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon
if [[ -f /Library/MonitoringClient/Utilities/ExportStatus ]]; then url=$(/usr/bin/defaults read /Library/MonitoringClient/ClientData/UnifiedStatus.plist ClientURL 2>/dev/null) echo "<result>${url:-Unknown}</result>" else echo "<result>Watchman Monitoring not installed</result>" fi
